create table lc_amendment (id uuid primary key, lc_id uuid not null references letter_of_credit(id) on delete cascade, amendment_number varchar(255), amendment_date date, amount_increase numeric(19,2), amount_decrease numeric(19,2), new_expiry_date date, new_expiry_place varchar(255), new_latest_shipment_date date, changed_documents varchar(4000), raw_message text, imported_at timestamp); create index idx_lc_amendment_lc on lc_amendment(lc_id);
